import React, { useState } from 'react';
import './index.css';

function App() {
  const [page, setPage] = useState("login");

  return (
    <div>
      {page === "login" && <LoginPage setPage={setPage} />}
      {page === "trivia" && <TriviaPage setPage={setPage} />}
    </div>
  );
}

function LoginPage({ setPage }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");

  return (
    <div className="flex h-screen">
      <div className="w-1/2 bg-blue-500 p-8 text-white">
        <h1 className="text-2xl font-bold italic">Rules</h1>
        <p className="mt-4 italic">
          Lorem ipsum dolor sit amet, consectetur adipiscing elit...
        </p>
      </div>
      <div className="w-1/2 bg-gray-200 flex flex-col items-center justify-center p-8">
        <div className="text-center">
          <img src="/logo.png" alt="Trivia Game" className="w-20 mx-auto" />
          <h1 className="text-3xl font-bold">TRIVIA GAME</h1>
          <input
            className="mt-4 p-2 border rounded w-full"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <input
            className="mt-2 p-2 border rounded w-full"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <button
            className="mt-4 p-2 bg-blue-500 text-white rounded w-full"
            onClick={() => setPage("trivia")}
          >
            Login
          </button>
          <button className="mt-2 p-2 bg-orange-500 text-white rounded w-full">
            Leaderboard
          </button>
        </div>
      </div>
    </div>
  );
}

function TriviaPage({ setPage }) {
  return (
    <div className="flex h-screen">
      <div className="w-1/2 bg-blue-500 p-8 text-white">
        <h1 className="text-2xl font-bold italic">Question 1</h1>
        <div className="mt-4 flex flex-col space-y-4">
          <button className="p-4 bg-yellow-300 rounded text-lg">?</button>
          <button className="p-4 bg-yellow-300 rounded text-lg">?</button>
          <button className="p-4 bg-yellow-300 rounded text-lg">?</button>
        </div>
      </div>
      <div className="w-1/2 bg-gray-200 flex flex-col items-center justify-center p-8">
        <h1 className="text-5xl">30</h1>
        <input
          className="mt-4 p-2 border rounded w-full"
          placeholder="Type Your Answer here"
        />
        <button className="mt-4 p-2 bg-blue-500 text-white rounded w-full">
          Submit
        </button>
        <button className="mt-2 p-2 bg-gray-500 text-white rounded w-full" onClick={() => setPage("login")}>
          Back to Login
        </button>
        <img src="/logo.png" alt="Trivia Game" className="w-12 mt-4" />
      </div>
    </div>
  );
}

export default App;
